interface LogLine {
  level: string;
  category: string;
  message: string;
  fields?: Record<string, unknown>;
}

/** Captures all log lines for test assertions; call restoreLogger to restore the default logger. */
export function captureLogger(): LogLine[] {
  const logLines: LogLine[] = [];
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
  return logLines;
}

